(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*20 + Math.cos(y*0.012-t*0.18)*15;
  const w1y = Math.cos(y*0.018-t*0.22)*20 + Math.sin(x*0.015+t*0.3)*15;
  const w2x = Math.sin((x+w1x)*0.025+t*0.15)*10 + Math.cos((y+w1y)*0.02-t*0.12)*8;
  const w2y = Math.cos((y+w1y)*0.022-t*0.2)*10 + Math.sin((x+w1x)*0.019+t*0.17)*8;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,1.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.9],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,1.1],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.85],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,1.05],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.95],
    [80+Math.sin(t*0.45+3)*60,40+Math.cos(t*0.65+1)*50,0.11,2.1,1.0],
    [400+Math.cos(t*0.55+2)*70,200+Math.sin(t*0.75+4)*60,0.075,1.8,0.9],
    [240+Math.sin(t*0.25)*180,120+Math.cos(t*0.45+2)*110,0.05,2.8,1.15]
  ];
  let aS=0,iS=0,hS=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp)*w;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    hS+=Math.sin(d*f*0.5+t*sp*0.3+3.0)*w*0.5;
  }
  const n=src.length,act=aS/n,inh=iS/n,har=hS/n;
  let bg=0,amp=0.5,freq=0.03;
  for(let i=0;i<4;i++){
    bg+=amp*Math.sin(sx*freq+sy*freq*0.7+t*(0.5+i*0.2))*Math.cos(sx*freq*0.8-sy*freq*1.1+t*(0.3+i*0.15));
    amp*=0.5;freq*=2.1;
  }
  bg+=Math.sin((sx+sy)*0.08+t*1.8)*0.15+Math.sin((sx-sy)*0.1-t*1.5)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.045-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.35+Math.sin(dist*0.03-ang*5+t*0.8)*0.2;
  const cX=sx*0.08,cY=sy*0.08,ci=Math.floor(cX),cj=Math.floor(cY);
  let minD=99,minD2=99;
  for(let di=-1;di<=1;di++)for(let dj=-1;dj<=1;dj++){
    const ni=ci+di,nj=cj+dj;
    const px=ni+0.5+Math.sin(ni*12.9898+nj*78.233+t*0.5)*0.45;
    const py=nj+0.5+Math.cos(ni*78.233+nj*12.9898-t*0.4)*0.45;
    const d=Math.sqrt((cX-px)**2+(cY-py)**2);
    if(d<minD){minD2=minD;minD=d;}else if(d<minD2)minD2=d;
  }
  const cellEdge=Math.min(1,(minD2-minD)*3);
  const reaction=Math.tanh((act-inh*0.65+bg*0.25+spiral+har*0.15)*2.0);
  const cellC=Math.tanh((minD-0.5)*4)*0.3;
  const blend=reaction*0.7+cellC*0.15+(1-cellEdge)*0.15;
  const v=blend*0.5+0.5;
  const pal=[[5,12,45],[12,40,85],[18,75,120],[25,130,135],[45,175,140],[160,195,90],[230,200,60],[235,150,50],[210,90,55],[175,50,70],[120,30,80],[60,20,75],[20,15,55],[5,12,45]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i,sf=f*f*(3-2*f);
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15;
  const edge=Math.abs(reaction)>0.65?1.1:1.0;
  const cg=(1-cellEdge)*0.15;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*lum*edge+cg*40))|0,
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*lum*edge+cg*60))|0,
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*lum*edge+cg*80))|0
  ];
}
